windowclass.script:
function onInit()
	-- Set up handler to recalculate SB when attributes change
	local node = getDatabaseNode();
	if node then
		DB.addHandler(node.getPath() .. ".att1", "onUpdate", recalculateSB);
		DB.addHandler(node.getPath() .. ".att2", "onUpdate", recalculateSB);
	end
end

function onClose()
	local node = getDatabaseNode();
	if node then
		DB.removeHandler(node.getPath() .. ".att1", "onUpdate", recalculateSB);
		DB.removeHandler(node.getPath() .. ".att2", "onUpdate", recalculateSB);
	end
end

function recalculateSB()
	local node = getDatabaseNode();
	if not node then return; end

	local sAtt1 = DB.getValue(node, "att1", "");
	local sAtt2 = DB.getValue(node, "att2", "");
	if sAtt1 == "" or sAtt2 == "" then return; end

	-- Navigate to NPC node (skill -> skills -> npc)
	local nodeNPC = node.getParent().getParent();
	if not nodeNPC then return; end

	-- Use SkillsManager if available
	if SkillsManager and SkillsManager.calculateSB then
		local nSB = SkillsManager.calculateSB(nodeNPC, sAtt1, sAtt2);
		DB.setValue(node, "sb", "number", nSB);
	end
end

stringfield.script:
function onLoseFocus()
	local sName = getValue();
	if sName == "" then return; end

	Debug.console("NPC Skill name entered: " .. sName);

	-- Look up skill data from database
	local nodeSkillsRef = DB.findNode("harnmaster.skills");
	if nodeSkillsRef then
		for _, nodeRefSkill in pairs(DB.getChildren(nodeSkillsRef)) do
			if DB.getValue(nodeRefSkill, "name", "") == sName then
				local sAtt1 = DB.getValue(nodeRefSkill, "att1", "");
				local sAtt2 = DB.getValue(nodeRefSkill, "att2", "");

				Debug.console("Found skill: att1=" .. sAtt1 .. ", att2=" .. sAtt2);

				-- Update att1, att2 fields in NPC's skill entry
				local nodeSkill = window.getDatabaseNode();
				if nodeSkill then
					DB.setValue(nodeSkill, "att1", "string", sAtt1);
					DB.setValue(nodeSkill, "att2", "string", sAtt2);

					-- Navigate to NPC node and calculate SB directly
					local nodeNPC = nodeSkill.getParent().getParent();
					Debug.console("nodeSkill path: " .. DB.getPath(nodeSkill));
					Debug.console("nodeNPC path: " .. DB.getPath(nodeNPC));

					-- Get attribute values directly
					local sAtt1Field = string.lower(sAtt1) .. "_score";
					local sAtt2Field = string.lower(sAtt2) .. "_score";
					local nAtt1 = DB.getValue(nodeNPC, sAtt1Field, 0);
					local nAtt2 = DB.getValue(nodeNPC, sAtt2Field, 0);

					Debug.console(sAtt1 .. " (" .. sAtt1Field .. ") = " .. tostring(nAtt1));
					Debug.console(sAtt2 .. " (" .. sAtt2Field .. ") = " .. tostring(nAtt2));

					-- Calculate SB: average, round up if att1 > att2, else round down
					local nSB = 0;
					if nAtt1 > 0 or nAtt2 > 0 then
						local nSum = nAtt1 + nAtt2;
						if nAtt1 > nAtt2 then
							nSB = math.ceil(nSum / 2);
						else
							nSB = math.floor(nSum / 2);
						end
					end

					Debug.console("Calculated SB: " .. tostring(nSB));
					DB.setValue(nodeSkill, "sb", "number", nSB);
				end
				return;
			end
		end
		Debug.console("NPC Skill not found in harnmaster.skills: " .. sName);
	else
		Debug.console("ERROR: harnmaster.skills node not found");
	end
end

windowclass.script:
local sPossessionDeletePath = nil;
local sArmourDeletePath = nil;
local sStrScorePath = nil;

function onInit()
	WindowTabManager.populate(self);

	local nodeChar = getDatabaseNode();
	if nodeChar then
		-- Watch for possession deletions
		sPossessionDeletePath = DB.getPath(nodeChar, "possessions") .. ".*";
		DB.addHandler(sPossessionDeletePath, "onDelete", onPossessionDeleted);

		-- Watch for armour deletions
		sArmourDeletePath = DB.getPath(nodeChar, "armourlist") .. ".*";
		DB.addHandler(sArmourDeletePath, "onDelete", onArmourDeleted);

		-- Watch for STR changes (affects Str Mod and Total ENC)
		sStrScorePath = DB.getPath(nodeChar, "str_score");
		DB.addHandler(sStrScorePath, "onUpdate", onStrScoreChanged);

		-- Watch for Fatigue changes
		DB.addHandler(DB.getPath(nodeChar, "winded"), "onUpdate", onMoveRelatedChanged);
		DB.addHandler(DB.getPath(nodeChar, "weary"), "onUpdate", onMoveRelatedChanged);
		DB.addHandler(DB.getPath(nodeChar, "weak"), "onUpdate", onMoveRelatedChanged);

		-- Watch for Injury changes
		DB.addHandler(DB.getPath(nodeChar, "imp_head"), "onUpdate", onMoveRelatedChanged);
		DB.addHandler(DB.getPath(nodeChar, "imp_torso"), "onUpdate", onMoveRelatedChanged);
		DB.addHandler(DB.getPath(nodeChar, "imp_leg_l"), "onUpdate", onMoveRelatedChanged);
		DB.addHandler(DB.getPath(nodeChar, "imp_leg_r"), "onUpdate", onMoveRelatedChanged);
	end
end

function onClose()
	local nodeChar = getDatabaseNode();
	if nodeChar then
		if sPossessionDeletePath then
			DB.removeHandler(sPossessionDeletePath, "onDelete", onPossessionDeleted);
		end
		if sArmourDeletePath then
			DB.removeHandler(sArmourDeletePath, "onDelete", onArmourDeleted);
		end
		if sStrScorePath then
			DB.removeHandler(sStrScorePath, "onUpdate", onStrScoreChanged);
		end

		-- Remove Fatigue handlers
		DB.removeHandler(DB.getPath(nodeChar, "winded"), "onUpdate", onMoveRelatedChanged);
		DB.removeHandler(DB.getPath(nodeChar, "weary"), "onUpdate", onMoveRelatedChanged);
		DB.removeHandler(DB.getPath(nodeChar, "weak"), "onUpdate", onMoveRelatedChanged);

		-- Remove Injury handlers
		DB.removeHandler(DB.getPath(nodeChar, "imp_head"), "onUpdate", onMoveRelatedChanged);
		DB.removeHandler(DB.getPath(nodeChar, "imp_torso"), "onUpdate", onMoveRelatedChanged);
		DB.removeHandler(DB.getPath(nodeChar, "imp_leg_l"), "onUpdate", onMoveRelatedChanged);
		DB.removeHandler(DB.getPath(nodeChar, "imp_leg_r"), "onUpdate", onMoveRelatedChanged);
	end
end

function onPossessionDeleted(nodeDeleted)
	local nodeChar = getDatabaseNode();
	if nodeChar and ArmorManager then
		ArmorManager.calculateGear(nodeChar);
	end
end

function onArmourDeleted(nodeDeleted)
	local nodeChar = getDatabaseNode();
	if nodeChar and ArmorManager then
		-- Pass nodeDeleted to avoid its values in recalc (it's still in DB during handler)
		ArmorManager.calculateArmor(nodeChar, nodeDeleted);
	end
end

function onStrScoreChanged(nodeField)
	local nodeChar = getDatabaseNode();
	if nodeChar and ArmorManager then
		-- Str Mod logic is inside calculateGear
		ArmorManager.calculateGear(nodeChar);
	end
end

function onMoveRelatedChanged(nodeField)
	local nodeChar = getDatabaseNode();
	if nodeChar and HarnManager and HarnManager.calculateEffectiveMove then
		HarnManager.calculateEffectiveMove(nodeChar);
	end
end

-- Recalculate all NPC skill SBs when attributes change
function recalculateNPCSkills()
	local nodeNPC = getDatabaseNode();
	if not nodeNPC then return; end

	local nodeSkillsList = DB.getChild(nodeNPC, "skills");
	if not nodeSkillsList then return; end

	for _, nodeSkill in ipairs(DB.getChildList(nodeSkillsList)) do
		local sAtt1 = DB.getValue(nodeSkill, "att1", "");
		local sAtt2 = DB.getValue(nodeSkill, "att2", "");

		if sAtt1 ~= "" and sAtt2 ~= "" then
			local sAtt1Field = string.lower(sAtt1) .. "_score";
			local sAtt2Field = string.lower(sAtt2) .. "_score";
			local nAtt1 = DB.getValue(nodeNPC, sAtt1Field, 0);
			local nAtt2 = DB.getValue(nodeNPC, sAtt2Field, 0);

			local nSB = 0;
			if nAtt1 > 0 or nAtt2 > 0 then
				local nSum = nAtt1 + nAtt2;
				if nAtt1 > nAtt2 then
					nSB = math.ceil(nSum / 2);
				else
					nSB = math.floor(nSum / 2);
				end
			end

			DB.setValue(nodeSkill, "sb", "number", nSB);
		end
	end
end

