stringfield.script:
function onInit()
	updateDisplay();
end
function updateDisplay()
	local nMorality = 0;
	if window.morality then
		nMorality = window.morality.getValue() or 0;
	end
	local sText = "";
	if nMorality >= 17 then
		sText = "Exemplary";
	elseif nMorality >= 14 then
		sText = "Principled";
	elseif nMorality >= 11 then
		sText = "Dutiful";
	elseif nMorality >= 8 then
		sText = "Corruptible";
	elseif nMorality >= 5 then
		sText = "Unscrupulous";
	elseif nMorality >= 1 then
		sText = "Diabolical";
	end
	setValue(sText);
end

windowclass.script:
local bEditMode = false;

function onInit()
	updateAllVisuals();
	-- Disable status icon buttons by default (only clickable in edit mode)
	icon_bld.setEnabled(false);
	icon_shk.setEnabled(false);
	icon_amp.setEnabled(false);
end

function setEditMode(bMode)
	Debug.console("Entry setEditMode called with: " .. tostring(bMode));
	bEditMode = bMode;
	Debug.console("Entry bEditMode now: " .. tostring(bEditMode));
	-- Toggle field editability (disabled when in edit mode so clicks cycle instead)
	zone_range.setEnabled(not bMode);
	zone_name.setEnabled(not bMode);
	loc_range.setEnabled(not bMode);
	location.setEnabled(not bMode);
	av_b.setEnabled(not bMode);
	av_e.setEnabled(not bMode);
	av_p.setEnabled(not bMode);
	av_f.setEnabled(not bMode);
	-- Toggle delete button visibility
	idelete.setVisible(bMode);
	-- Enable/disable status icon buttons (only clickable in edit mode)
	icon_bld.setEnabled(bMode);
	icon_shk.setEnabled(bMode);
	icon_amp.setEnabled(bMode);
end

function isEditMode()
	return bEditMode;
end

-- Armor tier cycling for BEPF fields
function cycleArmorB()
	Debug.console("cycleArmorB called, bEditMode=" .. tostring(bEditMode));
	if not bEditMode then return; end
	local n = (tier_b.getValue() + 1) % 4;
	Debug.console("Setting tier_b to " .. tostring(n));
	tier_b.setValue(n);
end
function cycleArmorE()
	if not bEditMode then return; end
	local n = (tier_e.getValue() + 1) % 4;
	tier_e.setValue(n);
end
function cycleArmorP()
	if not bEditMode then return; end
	local n = (tier_p.getValue() + 1) % 4;
	tier_p.setValue(n);
end
function cycleArmorF()
	if not bEditMode then return; end
	local n = (tier_f.getValue() + 1) % 4;
	tier_f.setValue(n);
end

-- Icon cycling for BLD/SHK/AMP
function cycleBLD()
	Debug.console("cycleBLD called, bEditMode=" .. tostring(bEditMode));
	if not bEditMode then return; end
	local n = (bld_level.getValue() + 1) % 4;
	bld_level.setValue(n);
end
function cycleSHK()
	if not bEditMode then return; end
	local n = (shk_level.getValue() + 1) % 7;
	shk_level.setValue(n);
end
function cycleAMP()
	if not bEditMode then return; end
	local n = (amp_level.getValue() + 1) % 4;
	amp_level.setValue(n);
end

function updateAllVisuals()
	updateArmorVisuals();
	updateStatusIcons();
end

function updateArmorVisuals()
	-- Update B armor background (buttoncontrol state) and text color
	local nB = tier_b.getValue();
	bg_b.setValue(nB);
	av_b.setColor((nB == 3) and "FFFFFFFF" or "FF000000");

	-- Update E armor background and text color
	local nE = tier_e.getValue();
	bg_e.setValue(nE);
	av_e.setColor((nE == 3) and "FFFFFFFF" or "FF000000");

	-- Update P armor background and text color
	local nP = tier_p.getValue();
	bg_p.setValue(nP);
	av_p.setColor((nP == 3) and "FFFFFFFF" or "FF000000");

	-- Update F armor background and text color
	local nF = tier_f.getValue();
	bg_f.setValue(nF);
	av_f.setColor((nF == 3) and "FFFFFFFF" or "FF000000");
end

function updateStatusIcons()
	-- Update buttoncontrol states (0=empty, 1-3=icons)
	icon_bld.setValue(bld_level.getValue());
	icon_shk.setValue(shk_level.getValue());
	icon_amp.setValue(amp_level.getValue());
end

