windowclass.script:
function onInit()
	updateHeal();
end

function updateHeal()
	local nodeEntry = getDatabaseNode();
	if not nodeEntry then return end

	local nInjuryHR = DB.getValue(nodeEntry, "injury_hr", 0);
	local nodeNPC = nodeEntry.getParent().getParent();
	local nHB = 0;
	if nodeNPC then
		nHB = DB.getValue(nodeNPC, "healing_base", 0);
	end

	local nHeal = nInjuryHR * nHB;
	heal.setValue(nHeal);
end

numberfield.script:
function onValueChanged()
	window.updateHeal();
end

windowclass.script:
function onInit()
	local nodeChar = getDatabaseNode();
	-- Handler for skill updates (ML changes)
	DB.addHandler(DB.getPath(nodeChar, "skills"), "onChildUpdate", onSkillUpdate);

	-- Initial sync of weapons from gear
	if MeleeData and MeleeData.syncMeleeWeapons then
		MeleeData.syncMeleeWeapons(nodeChar);
	end
	if MissileData and MissileData.syncMissileWeapons then
		MissileData.syncMissileWeapons(nodeChar);
	end
end

function onClose()
	local nodeChar = getDatabaseNode();
	DB.removeHandler(DB.getPath(nodeChar, "skills"), "onChildUpdate", onSkillUpdate);
end

function onSkillUpdate()
	local nodeChar = getDatabaseNode();
	if MeleeData and MeleeData.updateMeleeATKDEF then
		MeleeData.updateMeleeATKDEF(nodeChar);
	end
	if MissileData and MissileData.updateMissileATK then
		MissileData.updateMissileATK(nodeChar);
	end
	if HarnManager and HarnManager.calculateEffectiveMove then
		HarnManager.calculateEffectiveMove(nodeChar);
	end
end

function updateShockUI()
	local nState = shock_state.getValue();
	shock_none_btn.setValue(nState == 0 and 1 or 0);
	shock_stn_btn.setValue(nState == 1 and 1 or 0);
	shock_inc_btn.setValue(nState == 2 and 1 or 0);
	shock_unc_btn.setValue(nState == 3 and 1 or 0);
	shock_kia_btn.setValue(nState == 4 and 1 or 0);
end


-- Edit mode state for body locations
local bEditMode = false;

function toggleEditMode()
	bEditMode = not bEditMode;
	edit_mode_btn.setValue(bEditMode and 1 or 0);
	Debug.console("NPC toggleEditMode: " .. tostring(bEditMode));

	-- Notify all body location entries to update their state
	local windows = bodylocations.getWindows();
	Debug.console("NPC body location windows: " .. tostring(#windows));
	for _, wnd in pairs(windows) do
		Debug.console("Checking window for setEditMode...");
		if wnd.setEditMode then
			Debug.console("Calling setEditMode on window");
			wnd.setEditMode(bEditMode);
		else
			Debug.console("Window does not have setEditMode");
		end
	end
end

function updateInjuryHeals()
	-- Update heal values for all injuries when HB changes
	for _, wnd in pairs(npcinjuries.getWindows()) do
		if wnd.updateHeal then
			wnd.updateHeal();
		end
	end
end

